	t.Helper()
	fake := &fakeSearcher{}
	withImageSearcher(t, fake)
	return searchLot(t, groupedModel(t)), fake
}

func rfImage(name, desc string) []imagesearch.Image {
	return []imagesearch.Image{{Name: name, Repo: name, Description: desc}}
}

