### IS-06 — Filter the level-1 results by text and by registry
Epic : E1 — Priorité : Should — Effort : M (architect, was S)

En tant qu'utilisateur, je veux affiner les résultats déjà reçus afin de réduire une longue
liste sans relancer de requête.

**Critères d'acceptation**
1. Étant donné des résultats, quand j'appuie sur `/` et saisis `bit`, alors seules les lignes
   dont le nom ou la description contiennent `bit` (insensible à la casse) restent, sans
   requête réseau.
2. Étant donné des résultats de plusieurs registres, quand j'appuie sur `r`, alors le filtre de
   registre parcourt groupes, registres individuels puis « off », comme dans la table de tags.
3. Étant donné un seul registre ayant produit des résultats, alors `r` ne propose rien.
4. Étant donné aucun filtre, alors la barre de filtre est cachée ; avec un filtre actif elle
   affiche le jeton correspondant (Rule 136), et la hauteur de pied de page en tient compte.
5. Étant donné la barre de filtre ouverte, quand je tape `:`, alors le caractère va dans le
   champ et la palette de commandes ne s'ouvre pas ; `esc` ferme d'abord la barre.
6. Étant donné un filtre qui ne laisse aucune ligne, alors la table reste une table à l'en-tête
   seul (Rule 139).

**Hors périmètre** : filtre par type (verified, sponsored OSS) ; correction de la barre de
filtre maison du niveau 2 (écart existant avec Rule 136, non-objectif).
**Hypothèses** : Hypothèse: le niveau 1 prend la barre de `datatable`, le niveau 2 garde la
sienne ; le jeton de registre vit dans la barre de `datatable` et `filterStops` (aujourd'hui
câblé sur les tags) est généralisé.
**Questions ouvertes** : aucune.

---

### IS-07 — Walk a host's catalog only once
Epic : E1 — Priorité : Should — Effort : S (architect)

En tant qu'utilisateur d'un groupe Nexus dont les membres partagent un hôte, je veux que le
catalogue de cet hôte ne soit parcouru qu'une fois par recherche afin de ne pas payer N fois le
coût du `_catalog`.

**Critères d'acceptation**
func TestRCyclesTheGroupEachRegistryThenOffOnLevelOne(t *testing.T) {
	m, _ := rfAnswered(t)
	b := m.registryBrowser
	if m.GetFooterHeight() != 2 {
		t.Fatalf("fixture: footer height = %d, want 2", m.GetFooterHeight())
	}

	steps := []struct {
		label string
		rows  []string
	}{
		{b.filterLabel(resultFilter{groupSlug: "prod"}), []string{"nginx", "redis"}},
		{b.filterLabel(resultFilter{entryKey: rfM1}), []string{"nginx"}},
		{b.filterLabel(resultFilter{entryKey: rfM2}), []string{"redis"}},
		{b.filterLabel(resultFilter{entryKey: rfHub}), []string{"nginx-hub"}},
	}
	for i, s := range steps {
		m = feed(t, m, testutil.Key("r"))
		rfWantNames(t, m, s.rows...)
		if !b.FilterIsVisible() {
			t.Errorf("stop %d: the bar is hidden", i)
		}
		if !strings.Contains(rfBar(m), s.label) {
			t.Errorf("stop %d: token %q missing in the bar %q", i, s.label, rfBar(m))
		}
		if got := m.GetFooterHeight(); got != 4 {
			t.Errorf("stop %d: footer height = %d, want 4", i, got)
		}
		if got := lvl1Header(t, m, "Images"); got != strconv.Itoa(len(s.rows)) {
			t.Errorf("stop %d: Images = %q, want %d", i, got, len(s.rows))
		}
	}
	m = feed(t, m, testutil.Key("r"))
	rfWantNames(t, m, "nginx", "redis", "nginx-hub")
	if b.FilterIsVisible() {
		t.Error("off: the bar is still visible")
	}
	if got := m.GetFooterHeight(); got != 2 {
		t.Errorf("off: footer height = %d, want 2", got)
	}
}

// The cursor follows its row through the narrowing.
func TestRDotAndColonTypedInTheOpenBarGoToTheField(t *testing.T) {
	m, _ := rfAnswered(t)
	b := m.registryBrowser
	m = feed(t, m, testutil.Key("r")) // group prod
	m = feed(t, m, testutil.Key("/"))
	m = feed(t, m, testutil.Type("r.:")...)
	if !b.searchTable.InEditMode() {
		t.Fatal("the bar closed")
	}
	if got := b.searchTable.FilterBar().SearchQuery(); got != "r.:" {
		t.Errorf("the field holds %q, want %q", got, "r.:")
	}
	if !strings.Contains(rfBar(m), "r.:") {
		t.Errorf("the bar does not show r.: (%q)", rfBar(m))
	}
	if col, desc := b.searchTable.SortState(); col != -1 || desc {
		t.Errorf("SortState = (%d,%v): the dot sorted", col, desc)
	}
	if label := b.filterLabel(resultFilter{groupSlug: "prod"}); !strings.Contains(rfBar(m), label) {
		t.Errorf("the r token %q left the bar: %q", label, rfBar(m))
	}
	m = feed(t, m, testutil.Key("esc"))
	b = m.registryBrowser
	if b.state != browserStateImages || b.searchTable.InEditMode() {
		t.Fatalf("esc: state %d, edit mode %v", b.state, b.searchTable.InEditMode())
	}
	if !b.FilterIsVisible() {
		t.Error("esc dropped the r filter")
	}
}

// AC6: nothing left after r and a query: a header-only table, still full width.
func TestRWithAQueryThatKeepsNothingLeavesAHeaderOnlyTable(t *testing.T) {
func TestTheGroupStopSurvivesAForeignKeyWithPartialMembers(t *testing.T) {
	cache := groupCacheFixture()
	g := cache["prod"]
	g.Members = append(g.Members, cacheMember("registry.example.com", "third", "third-proxy"))
	cache["prod"] = g
	m := feed(t, loadedModel(t), RegistryGroupCacheLoadedMsg{Entries: cache})
	m = feed(t, m, testutil.Key(keymap.Browser))
	m = typeInto(t, m, "api")
	m = feed(t, m, testutil.Key("enter"))
	m = feed(t, m, stampGen(m,
		MultiRegistryTagsLoadedMsg{EntryKey: memberKey("prod", "registry.example.com", "docker-hosted"), RegistryURL: "registry.example.com", Alias: "prod/docker-hosted", Repo: "docker-hosted/api", Tags: []string{"v1"}},
		MultiRegistryTagsLoadedMsg{EntryKey: memberKey("prod", "registry.example.com", "dhi-proxy"), RegistryURL: "registry.example.com", Alias: "prod/dhi", Repo: "dhi-proxy/api", Tags: []string{"v2"}},
		MultiRegistryTagsLoadedMsg{EntryKey: "hub", RegistryURL: "docker.io", Alias: "hub", Repo: "api", Tags: []string{"latest"}},
	)...)

